"""Render shared static components and new learning pages. Python standard library only."""
from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parent.parent
E=html.escape
def load(n):return json.loads((ROOT/'data'/f'{n}.json').read_text())
mods=load('modules');questions=load('questions');cases=load('cases');challenge=load('challenges')
